function validate([root, startValue, destValue]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs a root node.';
  const values = root.filter(v => v !== null);
  const n = values.length;
  if (n < 2 || n > 100000) return 'The tree needs 2 to 10^5 nodes.';
  const seen = new Set(values);
  if (seen.size !== n || values.some(v => !Number.isInteger(v) || v < 1 || v > n)) return 'Node values must be 1 to n, each used once.';
  // Every value after the root must hang under an earlier node.
  let slots = 2, next = 1;
  for (; next < root.length && slots > 0; next++) {
    slots--;
    if (root[next] !== null) slots += 2;
  }
  if (next < root.length) return 'Every value after the root needs a parent node.';
  if (!seen.has(startValue) || !seen.has(destValue)) return 'startValue and destValue must be values in the tree.';
  if (startValue === destValue) return 'startValue and destValue must differ.';
  return null;
}

