function getDirections(root, startValue, destValue) {
  // Breadth-first search over the tree treated as an undirected graph, remembering the route to each node.
  const parent = new Map([[root, null]]);
  const byValue = new Map();
  const stack = [root];
  while (stack.length) {
    const node = stack.pop();
    byValue.set(node.val, node);
    for (const child of [node.left, node.right]) {
      if (child) { parent.set(child, node); stack.push(child); }
    }
  }
  const source = byValue.get(startValue);
  const route = new Map([[source, '']]);
  const queue = [source];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    if (node.val === destValue) return route.get(node);
    for (const [next, move] of [[node.left, 'L'], [node.right, 'R'], [parent.get(node), 'U']]) {
      if (next && !route.has(next)) { route.set(next, route.get(node) + move); queue.push(next); }
    }
  }
  return '';
}

