function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 900 + Math.floor(rand() * 90) : 2 + Math.floor(rand() * 11);
  // Some trees start with a long downward chain, which makes deep routes.
  const chain = large ? (rand() < 0.4 ? 100 + Math.floor(rand() * 400) : 1) : (rand() < 0.25 ? n : 1);
  const values = Array.from({ length: n }, (_, i) => i + 1);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [values[i], values[j]] = [values[j], values[i]];
  }
  const nodes = [{ val: values[0], left: null, right: null }];
  for (let i = 1; i < chain; i++) {
    nodes[i - 1][rand() < 0.5 ? 'left' : 'right'] = i;
    nodes.push({ val: values[i], left: null, right: null });
  }
  const slots = [[chain - 1, 'left'], [chain - 1, 'right']];
  for (let i = chain; i < n; i++) {
    const k = Math.floor(rand() * slots.length);
    const [parent, side] = slots[k];
    slots[k] = slots[slots.length - 1];
    slots.pop();
    nodes[parent][side] = i;
    nodes.push({ val: values[i], left: null, right: null });
    slots.push([i, 'left'], [i, 'right']);
  }
  // Level-order serialisation with null for missing children, trailing nulls removed.
  const out = [];
  const queue = [0];
  for (let q = 0; q < queue.length; q++) {
    if (queue[q] === null) { out.push(null); continue; }
    const node = nodes[queue[q]];
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  const startValue = 1 + Math.floor(rand() * n);
  let destValue = 1 + Math.floor(rand() * (n - 1));
  if (destValue >= startValue) destValue++;
  return [out, startValue, destValue];
}
